            mc.playerController.unwrap().pickItem(blockSlot)
            mc.playerController.onPlayerRightClick(thePlayer, theWorld, thePlayer.heldItem, blockPos!!, sideHit, hitVec)
            thePlayer.swingItem()
        }
    }

