### Describe the bypass and how to replicate it

A client can inject horizontal velocity while the player is inside a cobweb, and Grim does not appear to flag or setback this movement
This allows the player to move through cobwebs faster than vanilla behavior should allow
Expected behavior: Grim should flag or setback players moving faster than normally possible in cobwebs
Actual behavior: Grim currently does not flag this behavior
Maximum speed reached: up to ~3.79 BPS

Code to reproduce:
```java
public class Grim extends IMode<NoWeb> {
    private final DoubleSetting strength = new DoubleSetting("Strength", 0.8d, 0.3d, 1.05d).withDescription("Horizontal speed injected while inside cobwebs.");

    public Grim(String name, NoWeb parent) {
        super(name, parent);
        addSettings(strength);

        onEvent(PlayerTickEvent.class, event -> {
            if (!event.isPre()) return;
            if (mc.player == null || mc.level == null) return;
            if (mc.player.isSpectator() || mc.player.getAbilities().flying) return;
            if (!isInsideCobweb()) return;

            var move = mc.player.input.getMoveVector();
            float forward = move.y;
            float strafe = move.x;

            if (forward == 0f && strafe == 0f) return;

            Vector3d dir = inputDirection(forward, strafe);
            if (dir == null) return;

            double inject = strength.getValue() * 0.15 / 0.25;
            var velocity = mc.player.getDeltaMovement();

            mc.player.setDeltaMovement(
                    velocity.x + dir.x * inject,
                    velocity.y,
                    velocity.z + dir.z * inject
            );
        });
    }

    private boolean isInsideCobweb() {
        if (mc.player == null || mc.level == null) return false;

        AABB bb = mc.player.getBoundingBox();

        int minX = Mth.floor(bb.minX);
        int maxX = Mth.floor(bb.maxX);
        int minY = Mth.floor(bb.minY);
        int maxY = Mth.floor(bb.maxY);
        int minZ = Mth.floor(bb.minZ);
        int maxZ = Mth.floor(bb.maxZ);

        BlockPos.MutableBlockPos pos = new BlockPos.MutableBlockPos();

        for (int x = minX; x <= maxX; x++) {
            for (int y = minY; y <= maxY; y++) {
                for (int z = minZ; z <= maxZ; z++) {
                    pos.set(x, y, z);

                    if (mc.level.getBlockState(pos).getBlock() == Blocks.COBWEB) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    private Vector3d inputDirection(float forward, float strafe) {
        if (mc.player == null) return null;

        float f = Mth.clamp(forward, -1f, 1f);
        float s = Mth.clamp(strafe, -1f, 1f);

        double yaw = Math.toRadians(mc.player.getYRot());
        double sin = Math.sin(yaw);
        double cos = Math.cos(yaw);

        double x = s * cos - f * sin;
        double z = f * cos + s * sin;

        double len = Math.sqrt(x * x + z * z);
        if (len < 1.0E-6) return new Vector3d();

        return new Vector3d(x / len, 0.0, z / len);
    }
}
